		s.TrackID, s.ComputedAt, s.ReadingCount,
		s.MeanDoserate, s.MedianDoserate, s.StddevDoserate,
		s.Threshold, s.AnomalyCount, string(idsJSON),
		s.AnomalyMax, s.AnomalyMin,
	); err != nil {
