<div class="page-content">
	<div class="admin-tabs">
		<a href="/admin/users` + func() string {
		if password != "" {
			return "?password=" + password
		}
		return ""
	}() + `">Users</a>
		<a href="/admin/uploads` + func() string {
		if password != "" {
			return "?password=" + password
		}
		return ""
	}() + `" class="active">Uploads</a>
		<a href="/admin/mcp` + func() string {
		if password != "" {
			return "?password=" + password
		}
		return ""
	}() + `">MCP Analytics</a>
