			// Toggle sort direction
			const currentDir = sortDirection[columnIndex] || 'none';
			sortDirection[columnIndex] = currentDir === 'asc' ? 'desc' : 'asc';

			// Remove sort classes from all headers
			table.querySelectorAll('.sortable').forEach(h => {
