			return
		}
		adminAnomalyDataHandler(w, r)
	}))
	http.HandleFunc("/api/admin/anomaly/rerun/", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
		if !checkAdminAccess(w, r) {
			return
		}
		adminAnomalyRerunHandler(w, r)
	}))

}

