// ── Spectrum anomaly table ──────────────────────────────────────────────────
let specSort = 'computed_at', specOrder = 'desc', specSearch = '', specOffset = 0, specLimit = 50, specTotal = 0, specData = [];

function doSpecSearch() { specSearch = document.getElementById('specSearchInput').value.trim(); specOffset = 0; fetchSpecData(); }
function clearSpecSearch() { document.getElementById('specSearchInput').value=''; specSearch=''; specOffset=0; fetchSpecData(); }

function specSortBy(col) {
  if (specSort === col) { specOrder = specOrder === 'desc' ? 'asc' : 'desc'; }
  else { specSort = col; specOrder = 'desc'; }
  specOffset = 0; fetchSpecData(); updateSpecSortIndicators();
}

function updateSpecSortIndicators() {
  document.querySelectorAll('#specTable th.sortable').forEach(th => {
    th.classList.remove('asc','desc');
    const col = th.getAttribute('onclick')?.match(/specSortBy\('(\w+)'\)/)?.[1];
    if (col === specSort) th.classList.add(specOrder);
  });
}

async function fetchSpecData() {
  const loading = document.getElementById('specLoading');
  const table   = document.getElementById('specTable');
  const noData  = document.getElementById('specNoData');
  loading.style.display='block'; table.style.display='none'; noData.style.display='none';

  let url = `/api/admin/anomaly/spectrum-data?limit=${specLimit}&offset=${specOffset}&sort=${specSort}&order=${specOrder}`;
  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
  if (specSearch) url += '&search=' + encodeURIComponent(specSearch);

  try {
    const resp = await fetch(url);
    if (!resp.ok) { loading.textContent = 'HTTP ' + resp.status; return; }
    const json = await resp.json();
    specTotal = json.total; specData = json.data || [];
    loading.style.display = 'none';
    if (specData.length === 0) { noData.style.display='block'; document.getElementById('specSummary').textContent='No results'; document.getElementById('specPagination').innerHTML=''; return; }

    const tbody = document.getElementById('specTableBody');
    tbody.innerHTML = specData.map((row, idx) => `
      <tr>
        <td><code>${row.track_id}</code></td>
        <td>${formatDate(row.computed_at)}</td>
        <td>${row.spectrum_count.toLocaleString()}</td>
        <td>${anomalyBadge(row.anomaly_count)}</td>
        <td>${fmt(row.median_total_counts, 1)}</td>
        <td>${fmt(row.cosine_threshold, 2)}</td>
        <td>
          <a class="btn-view" href="/trackid/${row.track_id}" target="_blank">View</a>
          <button class="btn-rerun" id="spec-rerun-${idx}" onclick="specRerun('${row.track_id}',${idx})">Re-run</button>
        </td>
      </tr>`).join('');

    table.style.display='table'; updateSpecSortIndicators();
    const page = Math.floor(specOffset/specLimit)+1, totalPages = Math.ceil(specTotal/specLimit);
    document.getElementById('specSummary').textContent = `${specTotal} track${specTotal!==1?'s':''} analysed | Page ${page} of ${totalPages}`;
    buildSpecPagination(totalPages, page);
  } catch(err) { loading.textContent = 'Error: ' + err.message; }
}

async function specRerun(trackID, idx) {
  const btn = document.getElementById('spec-rerun-' + idx);
  if (btn) { btn.disabled=true; btn.textContent='...'; }
  let url = `/api/admin/anomaly/spectrum-rerun/${trackID}` + AUTH_PARAM;
  try {
    const resp = await fetch(url, { method: 'POST' });
    if (!resp.ok) throw new Error('HTTP ' + resp.status);
    setTimeout(() => fetchSpecData(), 4000);
  } catch(e) {
    alert('Re-run failed: ' + e.message);
    if (btn) { btn.disabled=false; btn.textContent='Re-run'; }
  }
}

function buildSpecPagination(totalPages, currentPage) {
  const container = document.getElementById('specPagination');
  let html = `<button ${currentPage<=1?'disabled':''} onclick="goSpecPage(1)">First</button>`;
  html += `<button ${currentPage<=1?'disabled':''} onclick="goSpecPage(${currentPage-1})">Prev</button>`;
  let start=Math.max(1,currentPage-3), end=Math.min(totalPages,start+6); start=Math.max(1,end-6);
  for (let i=start;i<=end;i++) html+=`<button class="${i===currentPage?'active':''}" onclick="goSpecPage(${i})">${i}</button>`;
  html+=`<button ${currentPage>=totalPages?'disabled':''} onclick="goSpecPage(${currentPage+1})">Next</button>`;
  html+=`<button ${currentPage>=totalPages?'disabled':''} onclick="goSpecPage(${totalPages})">Last</button>`;
  html+=` <select onchange="changeSpecLimit(this.value)">${[25,50,100,200].map(n=>`<option value="${n}" ${n===specLimit?'selected':''}>${n} per page</option>`).join('')}</select>`;
  container.innerHTML = html;
}
function goSpecPage(p) { specOffset=(p-1)*specLimit; fetchSpecData(); }
function changeSpecLimit(v) { specLimit=parseInt(v); specOffset=0; fetchSpecData(); }

buildAdminTabs();
loadConfig();
fetchData();
fetchSpecData();

