// Upload progress tracking
type UploadProgress struct {
	Total            int
	Current          int
	Complete         bool
	Error            string
	RedirectURL      string
	NeedsCoordinates bool
	TrackID          string
	FileName         string
	mu               sync.RWMutex
}

var uploadProgress = struct {
	sync.RWMutex
	tracks map[string]*UploadProgress
