		}
		if req.Password != *adminPassword {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
	}

	// Validate trackIDs
	if len(req.TrackIDs) == 0 {
		http.Error(w, "trackIDs is required", http.StatusBadRequest)
